function opisz(zawod) {
  return `${this.imie} pracuje jako ${zawod}`;
}

console.log(opisz.call({ imie: "Tomek" }, "programista")); // "Tomek pracuje jako programista"
console.log(opisz.call({ imie: "Zosia" }, "lekarka"));      // "Zosia pracuje jako lekarka"

function policzRabat(procent) {
  return this.cena - (this.cena * procent) / 100;
}

console.log(policzRabat.call({ cena: 200 }, 10)); // 180

function przedstawZWiekiem(miasto) {
  return `${this.imie} (${this.wiek} lat) z ${miasto}`;
}

console.log(przedstawZWiekiem.call({ imie: "Ala", wiek: 30 }, "Gdansk"));
// "Ala (30 lat) z Gdansk"
console.log(przedstawZWiekiem.call({ imie: "Piotr", wiek: 45 }, "Poznan"));
// "Piotr (45 lat) z Poznan"

function pelnaCena() {
  return this.cenaNetto * (1 + this.vat);
}

console.log(pelnaCena.call({ cenaNetto: 100, vat: 0.23 })); // 123

function przywitaj(pora) {
  return `${pora}, ${this.imie}!`;
}

const osoby = [{ imie: "Ala" }, { imie: "Bartek" }, { imie: "Celina" }];

for (const osoba of osoby) {
  console.log(przywitaj.call(osoba, "Dzien dobry"));
}
// "Dzien dobry, Ala!"
// "Dzien dobry, Bartek!"
// "Dzien dobry, Celina!"

function obliczBMI() {
  return this.waga / (this.wzrost * this.wzrost);
}

console.log(obliczBMI.call({ waga: 70, wzrost: 1.75 }).toFixed(2)); // "22.86"

